import { cva, type VariantProps } from 'class-variance-authority'

export { default as PfAlert } from './PfAlert.vue'

export const alertVariants = cva(
  'relative grid w-full min-w-0 grid-cols-[auto_minmax(0,1fr)] gap-3 rounded-lg border p-4 text-sm',
  {
    variants: {
      type: {
        info: 'border-info/30 bg-info/10 text-info',
        success: 'border-success/30 bg-success/10 text-success',
        warning: 'border-warning/30 bg-warning/10 text-warning',
        error: 'border-error/30 bg-error/10 text-error',
      },
    },
    defaultVariants: {
      type: 'info',
    },
  },
)

export type AlertVariants = VariantProps<typeof alertVariants>

export interface PfAlertProps {
  type?: AlertVariants['type']
  title?: string
  description?: string
  icon?: string
  closable?: boolean
  class?: string
}

import type { ClassValue } from 'clsx'
import { clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

/**
 * 去除多行字符串的公共前导空白。
 * 类似 Python textwrap.dedent，用于保持 template literal 中代码块的整洁缩进。
 *
 * @example
 * dedent`
 *   import { ref } from 'vue'
 *   const count = ref(0)
 * `
 * // => "import { ref } from 'vue'\nconst count = ref(0)"
 */
export function dedent(strings: TemplateStringsArray, ...values: unknown[]): string {
  const raw = String.raw({ raw: strings }, ...values)
  return dedentStr(raw)
}

/**
 * 去除普通字符串的公共前导空白。
 * 用于处理已经构建好的代码字符串。
 */
export function dedentStr(raw: string): string {
  const lines = raw.split('\n')

  // 跳过首尾空行
  let start = 0
  let end = lines.length
  while (start < end && (lines[start] ?? '').trim() === '') start++
  while (end > start && (lines[end - 1] ?? '').trim() === '') end--
  const contentLines = lines.slice(start, end)

  if (contentLines.length === 0) return raw.trim()

  const minIndent = contentLines.reduce((min, line) => {
    const m = /^(\s*)/.exec(line)
    const indent = m?.[1]?.length ?? 0
    return Math.min(min, indent)
  }, Infinity)

  if (minIndent === Infinity || minIndent === 0) {
    return contentLines.join('\n').trimEnd()
  }

  const dedented = contentLines
    .map((line) => (line.length >= minIndent ? line.slice(minIndent) : line))
    .join('\n')

  return dedented.trimEnd()
}
